249	-- 5c. refund_escrow: validate company ownership
250	CREATE OR REPLACE FUNCTION refund_escrow(
251	    p_job_id UUID,
252	    p_reason TEXT DEFAULT 'Reembolso de vaga cancelada'
253	)
254	RETURNS TABLE(escrow_id UUID, escrow_amount DECIMAL)
255	LANGUAGE plpgsql
256	SECURITY DEFINER
257	SET search_path = public
258	AS $$
259	DECLARE
260	    v_escrow_id UUID;
261	    v_amount DECIMAL;
262	    v_company_wallet_id UUID;
263	    v_caller_wallet_id UUID;
264	BEGIN
265	    SELECT et.id, et.amount, et.company_wallet_id
266	    INTO v_escrow_id, v_amount, v_company_wallet_id
267	    FROM escrow_transactions et
268	    WHERE et.job_id = p_job_id AND et.status = 'reserved'
269	    FOR UPDATE;
270	
271	    IF NOT FOUND THEN
272	        RAISE EXCEPTION 'No reserved escrow found for job: %', p_job_id;
273	    END IF;
274	
275	    IF auth.uid() IS NOT NULL THEN
276	        SELECT id INTO v_caller_wallet_id
277	        FROM wallets WHERE user_id = auth.uid();
278	
279	        IF v_caller_wallet_id IS NULL OR v_caller_wallet_id != v_company_wallet_id THEN
280	            RAISE EXCEPTION 'Nao autorizado: voce nao e dono do escrow do job %', p_job_id;
281	        END IF;
282	    END IF;
283	
284	    UPDATE escrow_transactions
285	    SET status = 'refunded'
286	    WHERE id = v_escrow_id;
287	
288	    UPDATE wallets
289	    SET balance = balance + v_amount, updated_at = NOW()
290	    WHERE id = v_company_wallet_id;
291	
292	    INSERT INTO wallet_transactions(wallet_id, amount, type, description, reference_id)
293	    VALUES (v_company_wallet_id, v_amount, 'credit', p_reason, 'refund-' || p_job_id::TEXT);
294	
295	    RETURN QUERY SELECT v_escrow_id, v_amount;
296	END;
297	$$;
