299	-- 5d. credit_deposit: add search_path protection
300	CREATE OR REPLACE FUNCTION credit_deposit(
301	    p_user_id UUID,
302	    p_amount DECIMAL,
303	    p_payment_id TEXT,
304	    p_description TEXT DEFAULT 'Deposito via Pix'
305	)
306	RETURNS BOOLEAN
307	LANGUAGE plpgsql
308	SECURITY DEFINER
309	SET search_path = public
310	AS $$
311	DECLARE
312	    v_wallet_id UUID;
313	BEGIN
314	    SELECT id INTO v_wallet_id FROM wallets WHERE user_id = p_user_id;
315	    IF NOT FOUND THEN
316	        RAISE EXCEPTION 'Wallet not found for user: %', p_user_id;
317	    END IF;
318	
319	    INSERT INTO wallet_transactions(wallet_id, amount, type, description, reference_id)
320	    VALUES (v_wallet_id, p_amount, 'credit', p_description, p_payment_id)
321	    ON CONFLICT (wallet_id, reference_id) WHERE reference_id IS NOT NULL
322	    DO NOTHING;
323	
324	    IF NOT FOUND THEN
325	        RETURN FALSE;
326	    END IF;
327	
328	    UPDATE wallets
329	    SET balance = balance + p_amount, updated_at = NOW()
330	    WHERE id = v_wallet_id;
331	
332	    RETURN TRUE;
333	END;
334	$$;
