336	-- 5e. update_wallet_balance: add search_path protection
337	CREATE OR REPLACE FUNCTION update_wallet_balance(
338	    p_wallet_id UUID,
339	    p_amount DECIMAL
340	)
341	RETURNS DECIMAL
342	LANGUAGE plpgsql
343	SECURITY DEFINER
344	SET search_path = public
345	AS $$
346	DECLARE
347	    v_new_balance DECIMAL;
348	BEGIN
349	    UPDATE wallets
350	    SET balance = balance + p_amount, updated_at = NOW()
351	    WHERE id = p_wallet_id
352	    RETURNING balance INTO v_new_balance;
353	
354	    IF NOT FOUND THEN
355	        RAISE EXCEPTION 'Wallet not found: %', p_wallet_id;
356	    END IF;
357	
358	    RETURN v_new_balance;
359	END;
360	$$;
