299	        return { success: false, error: 'Erro ao registrar resposta.' };
300	      }
301	
302	      // 4. Notificação in-app para a empresa (best-effort)
303	      if (response === 'accepted') {
304	        // Buscar company para notificar o operador
305	        const { data: job } = await supabase
306	          .from('applications')
307	          .select('job:jobs(company_id)')
308	          .eq('id', applicationId)
309	          .maybeSingle();
310	
311	        // job.job é um objeto com company_id
312	        const companyId = (job?.job as { company_id?: string } | null)?.company_id;
313	
314	        if (companyId) {
315	          // Buscar owner da empresa
316	          const { data: company } = await supabase
317	            .from('companies')
318	            .select('owner_id')
